import {getMaintenanceDetail, addMaintenance, updateMaintenance} from "@/api/terminal";
export default {
  data() {
    return {
      id: '',
      form: {
        url: "",
        businessName: "",
        domainName: "",
      },
      loading: true,
      isEdit: true,
      btnLoading: false,
    };
  },
  async mounted() {
    // 设置页面元素高度
    this.setPageContentHeight()
    this.id = null;
    //获取参数 判断是否是新增还是修改
    const params = this.$route.query
    //params.id='1760851395719598082'
    this.id = params.id || '';
    if (params.id) {
      this.id = params.id;
      this.loadDetail(params.id);
      this.isEdit = true
    } else {
      //加载空数据
      this.beforeOpen();
      this.isEdit = true
    }
  },
  methods: {
    async handleSaveOK() {
      this.$refs.dataForm.validate(async (valid) => {
        if (valid) {
          this.btnLoading = true //按钮加载状态
          let saveRes = this.id ? await updateMaintenance(this.form) : await addMaintenance(this.form)
          if (saveRes[0] != null) {
            this.btnLoading = false
            return
          }
          this.btnLoading = false
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.handleReset();
        }
      })
    },
    handleReset() {
      //返回
      this.$closePage('/operation/safeaccess/switch');
    },
    beforeOpen() {
      getEmpty().then(res => {
        this.form = res.data;
        this.form.id = null;
        this.$forceUpdate()
      });
    },
    loadDetail(id) {
      getMaintenanceDetail(id).then(res => {
        this.form = res.data
        this.$refs.dataForm.$forceUpdate()
        this.$forceUpdate()
      });
    },
  }
};
